def transform(grid):
    # Extend diagonal sequences of each non-background color through empty cells.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Find diagonal runs of length >= 2; extend from their endpoints along the run direction,
    # stopping at the edge or another non-background cell.
    for dr in (-1, 1):
        for dc in (-1, 1):
            for r in range(h):
                for c in range(w):
                    color = grid[r][c]
                    if color == bg or not (0 <= r-dr < h and 0 <= c-dc < w):
                        continue
                    if grid[r-dr][c-dc] == color:
                        continue
                    # Start of a maximal run in this diagonal direction.
                    run=[]; rr,cc=r,c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr,cc)); rr+=dr; cc+=dc
                    if len(run) < 2:
                        continue
                    # extend both ends of maximal diagonal sequence
                    for endpoint, sr, sc, step_r, step_c in ((run[0],run[0][0]-dr,run[0][1]-dc,-dr,-dc),
                                                              (run[-1],run[-1][0]+dr,run[-1][1]+dc,dr,dc)):
                        er, ec = endpoint
                        # Adjacent marks at a segment endpoint signal that this end is capped.
                        if any(0 <= ar < h and 0 <= ac < w and grid[ar][ac] != bg
                               for ar, ac in ((er-1,ec),(er+1,ec),(er,ec-1),(er,ec+1))):
                            continue
                        rr,cc=sr,sc
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                            out[rr][cc]=color
                            rr+=step_r; cc+=step_c
    return out
